create or replace function pg_temp.gb(t text) returns text language plpgsql stable as $f$
declare r record; lt text;
begin
  if t is null or t = '' then return t; end if;
  lt := lower(t);
  for r in select us, uk from _gb where position(us in lt) > 0 order by length(us) desc loop
    t := regexp_replace(t, '\m' || r.us || '\M', r.uk, 'g');
    t := regexp_replace(t, '\m' || initcap(r.us) || '\M', initcap(r.uk), 'g');
  end loop;
  return t;
end $f$;
create or replace function pg_temp.gba(a text[]) returns text[] language sql stable as $f$
  select case when a is null then null else array(select pg_temp.gb(x) from unnest(a) with ordinality u(x, i) order by i) end
$f$;
